const state={page:location.hash.slice(1)||'background',output:'map',en:false,framework:0,district:'all',q:true,m:true,selected:null};
const t=(zh,en)=>state.en?en:zh;
const pages=['background','firm','sources','agent','output','conclusions'];
const navNames=[['研究背景','Background'],['研究企業','Chosen firm'],['所需資料來源','What data sources we need'],['Agent 如何運作','How this AI agent works'],['預期成果','How the expected output looks like'],['結論','Conclusions']];
const districts=[['all','全部區域','All areas'],['大安','大安區','Da’an'],['中山','中山區','Zhongshan'],['信義','信義區','Xinyi'],['中正','中正區','Zhongzheng']];
// Deliberately synthetic display positions. These are not real stores or geographic coordinates.
const pins=[['q',43,59,'大安'],['m',47,53,'大安'],['q',55,67,'大安'],['m',61,64,'大安'],['q',46,28,'中山'],['m',53,33,'中山'],['m',58,24,'中山'],['q',74,47,'信義'],['m',68,53,'信義'],['q',30,66,'中正'],['m',34,56,'中正'],['m',26,74,'中正']];
function go(page){state.page=pages.includes(page)?page:'background';location.hash=state.page;render();window.scrollTo(0,0)}
function head(k,title,desc){return `<div class="hero"><div><div class="eyebrow">${k}</div><h1>${title}</h1><p class="intro">${desc}</p></div><div class="seal"><div><small>CO-OPETITIVE</small><br>Breakfast<br>Atlas<br><small>TAIPEI · RESEARCH</small></div></div></div>`}
function section(title,en,right=''){return `<div class="section-title"><h2>${title}<small>${en}</small></h2>${right}</div>`}

function overview(){return head('A CLOSER LOOK AT EVERYDAY COMPETITION',t('一份早餐，<em>一場競合。</em>','Every breakfast.<br><em>A strategic choice.</em>'),t('從城市裡的每一家門市出發，探索 Q Burger 如何在成熟早餐市場切入、擴張，並維持競爭地位。','Explore how Q Burger enters, expands, and sustains its position in an established breakfast market, one neighborhood at a time.'))+`<div class="metrics">${[[t('焦點品牌','Focal brand'),'Q Burger',t('饗樂餐飲實業 · 名稱關係待核實','Company relationship to be verified')],[t('主要比較對象','Main comparator'),t('麥味登','My Warm Day'),t('品牌與公司資料分開處理','Separate brand and company data')],[t('空間研究範圍','Spatial scope'),t('台北市','Taipei'),t('暫定 · 待確認名單完整度','Tentative · coverage to be checked')],[t('研究資料狀態','Evidence status'),'TBD',t('尚未匯入已驗證研究資料','Verified research data not yet imported')]].map(x=>`<div class="metric"><label>${x[0]}</label><strong>${x[1]}</strong><span>${x[2]}</span></div>`).join('')}</div>`+section(t('走進品牌的競爭現場','Explore the competitive landscape'),'SPATIAL EXPLORER',`<button class="textbtn" data-go="map">${t('開啟完整探索','Explore atlas')} ↗</button>`)+mapBlock()+section(t('三個問題，讀懂策略選擇','Three questions behind strategy'),'THE RESEARCH QUESTIONS')+`<div class="cards">${[[t('如何切入？','How to enter?'),t('在既有品牌已布局的市場，客群、產品與店型如何找到新的位置？','How can customer focus, products, and formats create a position in an established market?')],[t('如何擴張？','How to expand?'),t('門市布局、加盟網絡與數位通路，如何支持品牌持續發展？','How can location choices, franchise networks, and digital channels support expansion?')],[t('如何維持競爭地位？','How to sustain?'),t('面對競爭，品牌如何經營顧客關係，並建立持續經營的能力？','How can brands maintain customer relationships and operating capabilities under competition?')]].map((x,i)=>`<button class="study" data-framework="${i}"><span class="index">0${i+1} <span style="float:right;font:16px Arial">↗</span></span><h3>${x[0]}</h3><p>${x[1]}</p><footer>${t('探索策略框架','Explore strategic frameworks')} →</footer></button>`).join('')}</div>`}
function mapBlock(){const selected=state.selected===null?null:pins[state.selected];return `<div class="map-grid"><div class="map-card"><div class="mapbar"><div class="legend"><label><input id="q-toggle" type="checkbox" ${state.q?'checked':''}><span class="dot"></span>Q Burger</label><label><input id="m-toggle" type="checkbox" ${state.m?'checked':''}><span class="dot" style="background:var(--green)"></span>${t('麥味登','MWD')}</label></div><select id="district" aria-label="${t('行政區篩選','Filter district')}">${districts.map(d=>`<option value="${d[0]}" ${state.district===d[0]?'selected':''}>${t(d[1],d[2])}</option>`).join('')}</select></div><div class="map"><svg viewBox="0 0 800 360" preserveAspectRatio="none" aria-label="${t('台北布局概念示意，非真實地圖','Conceptual spatial illustration, not a real map')}" role="img"><defs><pattern id="streets" width="47" height="41" patternTransform="rotate(-12)" patternUnits="userSpaceOnUse"><path d="M 0 0 L 47 0 M 0 0 L 0 41" fill="none" stroke="#fffdf6" stroke-width="6"/></pattern></defs><rect width="800" height="360" fill="#e9eedf"/><path d="M0 300L165 280 260 320 333 300 383 210 440 185 430 100 495 0" fill="none" stroke="#b9d7d0" stroke-width="29"/><path d="M90 0L130 100 80 175 0 160M640 0L700 100 800 113M730 360L680 300 800 260" fill="#d6e0c9"/><path d="M180 12L600 15 733 134 677 288 510 350 265 338 196 226 259 139Z" fill="url(#streets)"/><path d="M180 200L720 100M260 0L550 360M210 290L730 210" stroke="#d3c9ac" stroke-width="3" fill="none" stroke-dasharray="6 4"/><g fill="#7f8e75" font-size="13" font-family="sans-serif"><text x="370" y="70">${t('中山區','Zhongshan')}</text><text x="460" y="237">${t('大安區','Da’an')}</text><text x="610" y="137">${t('信義區','Xinyi')}</text><text x="175" y="240">${t('中正區','Zhongzheng')}</text><text x="600" y="320" font-size="10">CONCEPT MAP · NOT TO SCALE</text></g></svg>${pins.map((p,i)=>(state[p[0]]&&(state.district==='all'||p[3]===state.district))?`<button class="pin ${p[0]==='m'?'other':''}" style="left:${p[1]}%;top:${p[2]}%" data-pin="${i}" aria-label="${p[0]==='q'?'Q Burger':'My Warm Day'} ${t('虛構示意點','synthetic point')} ${i+1}"></button>`:'').join('')}<div class="mapnote">${t('● 示意點位 · 非真實門市與距離','● Synthetic points · not real stores or distances')}</div></div><div class="map-foot">${t('地圖僅供介面操作預覽。空間鄰近不直接代表顧客重疊、競爭強度或適合開店。','Interface preview only. Proximity does not establish customer overlap, competitive intensity, or site suitability.')}</div></div><div class="panel detail"><div class="mini">${selected?'DEMO POINT DETAILS':'READING THE LANDSCAPE'}</div><h3>${selected?`${selected[0]==='q'?'Q Burger':t('麥味登','My Warm Day')} · ${t('示意點','Demo')}`:t('競爭，從哪裡開始？','Where does competition begin?')}</h3><p>${selected?t('這是用於測試點擊互動的虛構點位，不代表真實門市。正式版將顯示名稱、地址與可追溯來源。','This synthetic point demonstrates interaction. Verified store names, addresses and traceable sources will be shown in the final version.'):t('切換品牌、選擇行政區，或點擊示意點位，探索未來如何閱讀品牌布局。','Toggle brands, select an area, or click a synthetic point to explore the atlas interface.')}</p><hr><div class="row"><span>${t('資料觀察日期','Observation date')}</span><b>TBD</b></div><div class="row"><span>${t('資料來源','Data source')}</span><b>${t('尚未匯入','Not imported')}</b></div><div class="row"><span>${t('距離計算方式','Distance method')}</span><b>TBD</b></div><hr><button class="textbtn" data-go="sources">${t('閱讀資料與方法','Read sources & methods')} ↗</button></div></div>`}
function mapPage(){return head('01 / SPATIAL EXPLORER',t('看見布局，<em>理解情境。</em>','See the locations.<br><em>Understand the context.</em>'),t('同一觀察日期、相同比較口徑。從區域重心與競品鄰近程度，建立空間競爭的研究起點。','Start with comparable store lists from a common observation date, then examine regional concentration and competitor proximity.'))+mapBlock()+section(t('品牌比較指標','Brand comparison metrics'),'COMPARABLE, BEFORE COMPARISON')+`<div class="grid2">${[t('行政區門市分布','Stores by district'),t('競品鄰近比例','Competitor proximity')].map(x=>`<div class="panel comparison"><h3>${x}</h3><div class="row"><span>Q Burger</span><b>TBD</b></div><div class="bar-empty"></div><div class="row"><span>${t('麥味登','My Warm Day')}</span><b>TBD</b></div><div class="bar-empty"></div><p class="intro" style="font-size:12px">${t('待匯入經查核的門市資料後計算；不以示意點位產生研究指標。','Pending verified store data. Synthetic points are excluded from research metrics.')}</p></div>`).join('')}</div>`}
const frameworks=[['PESTEL','外部環境','External environment'],['GAME','競合與賽局','Co-opetition & games'],['AMC','行動與回應','Action & response'],['PLATFORM','平台策略','Platform strategy'],['INSIGHTS','策略選項','Strategic options']];
const analyses=[
[['外部條件如何改變品牌選擇？','How do external conditions shape brand choices?'],['以政策、經濟、生活型態、科技、環境與法律，連結企業可以觀察的經營決策。以下為研究問題，尚非分析發現。','Connect policy, economics, lifestyles, technology, environmental and legal factors to observable decisions. These are research questions, not findings.'],[['P / 政策與制度','P / Policy'],['勞動、食品安全與加盟制度，可能影響哪些成本與管理責任？','How might labor, food safety and franchise rules affect costs and management responsibilities?']],[['E / 經濟環境','E / Economy'],['成本與消費條件改變時，品牌是否有具日期的價格、產品或效率措施？','Do dated price, product or efficiency actions accompany changes in costs and demand conditions?']],[['S / 社會情境','S / Society'],['住宅人口、交通背景與門市布局之間，有哪些可觀察的空間關係？','What spatial relationships can be observed between stores, residential population and transit?']],[['T / 科技與服務','T / Technology'],['點餐、支付與會員服務改變哪些流程？功能存在不等於成效已獲證明。','Which processes do ordering, payments and membership change? Features alone do not prove impact.']],[['E / 環境永續','E / Environmental'],['包材、廚餘與能源管理如何影響成本及差異化？措施成效須有證據。','How do packaging, food waste and energy management affect costs and differentiation? Benefits require evidence.']],[['L / 法律規範','L / Legal'],['食品安全、勞動、消費者保護與加盟法規帶來哪些責任？區分法定義務與自願措施，不自行推定合規或違規。','Which duties arise from food safety, labor, consumer protection and franchise rules? Distinguish legal duties from voluntary practices; do not infer compliance or violations.']]],
[['競爭與合作，同時發生。','Competition and collaboration coexist.'],['在區域案例中比較供給差異，並釐清加盟、外送與支付夥伴之間的資源交換及依賴。','Compare observable offerings in local cases and examine resource exchange and dependencies with franchisees, delivery and payment partners.'],[['競爭面向','Competitive dimensions'],['比較產品、價格帶、店型、營業時間及點餐服務；沒有交易資料，不判定顧客偏好。','Compare products, price ranges, formats, hours and ordering services; customer preferences require transaction or customer evidence.']],[['合作面向','Partner relationships'],['釐清各方的資源、價值與控制權張力；共用平台不等於兩品牌彼此合作。','Identify resources, value and control tensions. Using the same platform does not establish inter-brand cooperation.']],[['質性賽局情境','Qualitative scenarios'],['Q Burger 相近定位或差異化 × 對手維持或調整策略。討論利益、代價與條件，不虛設報酬或宣稱均衡。','Similar positioning or differentiation × competitor holds or adjusts strategy. Discuss trade-offs and conditions without invented payoffs or equilibrium claims.']]],
[['從事件出發，而非猜測意圖。','Start with events, not assumed intent.'],['每個事件沿著「事實 → AMC 解讀 → 對手行動 → 後續觀察 → 證據限制」展開。','For each event: facts → AMC interpretation → competitor actions → follow-up → evidence limits.'],[['A / 察覺 Awareness','A / Awareness'],['公司是否公開提及市場變化或特定競爭行動？無公開說法時標示無法確認。','Has the company publicly acknowledged a market change or specific competitive action? Otherwise mark it unconfirmed.']],[['M / 動機 Motivation','M / Motivation'],['區分公司公開目的與團隊推論，並保留替代解釋。','Separate the company’s stated purpose from team interpretations and retain alternative explanations.']],[['C / 能力 Capability','C / Capability'],['檢查加盟、供應、技術、管理與財務資源；資源存在不保證執行成功。','Examine franchise, supply, technology, management and financial resources. Resources do not guarantee execution.']]],
[['觸及顧客，也經營自主。','Reach customers. Build autonomy.'],['比較第三方外送、自有點餐與會員服務的功能、適用範圍與合作限制。','Compare third-party delivery, owned ordering and membership services by function, scope and partner constraints.'],[['接觸與交易','Discovery & transactions'],['顧客如何發現品牌、點餐、付款與取餐？個別門市的服務須另確認。','How do customers discover, order, pay and collect? Service availability needs store-level verification.']],[['顧客關係','Customer relationships'],['會員與再次購買入口由誰提供？無內部資料，不推估會員營收貢獻。','Who provides membership and repeat-purchase entry points? Revenue contribution requires internal evidence.']],[['合作與依賴','Cooperation & dependence'],['檢查公開可確認的成本與限制；未公開抽成、獲利與流量成效維持資料不足。','Check publicly verifiable costs and constraints. Undisclosed commissions, profits and traffic effects remain unknown.']]],
[['有條件的選項，才有討論價值。','Useful options come with conditions.'],['以下為提案中的候選研究方向，仍待資料支持與團隊確認。','These candidate directions come from the proposal and await supporting evidence and team review.'],[['01 / 重疊區域的差異化','01 / Differentiation in overlapping areas'],['觀察產品、店型與服務差異，透過顧客或交易資料驗證需求。','Observe product, format and service differences; validate demand with customer or transaction evidence.']],[['02 / 據點較少地區的發展','02 / Development in less-covered areas'],['先確認需求與經營條件，再評估發展可能；門市較少不等於市場空白。','Verify demand and operating conditions before evaluating expansion. Fewer stores do not establish unmet demand.']],[['03 / 加盟與通路搭配','03 / Franchise & channel mix'],['檢查管理能力及資源是否支持擴張，並評估第三方通路與自有服務的取捨。','Check management capacity and resources for expansion, then evaluate trade-offs between third-party and owned channels.']]]];
function strategy(){let a=analyses[state.framework];return head('02 / STRATEGY STUDIO',t('把觀察，<em>變成好問題。</em>','Turn observations<br><em>into better questions.</em>'),t('外部環境 → 門市布局 → 競合與賽局 → AMC → 平台策略 → 商業洞察。','External environment → Store locations → Co-opetition → AMC → Platform strategy → Business insights.'))+`<div class="tabs" role="tablist">${frameworks.map((x,i)=>`<button class="tab ${state.framework===i?'active':''}" role="tab" aria-selected="${state.framework===i}" data-tab="${i}">${x[0]} · ${t(x[1],x[2])}</button>`).join('')}</div><div class="panel analysis" role="tabpanel"><span class="badge">${t('研究框架 · 待驗證假設','Research framework · hypotheses pending')}</span><h3>${t(...a[0])}</h3><p>${t(...a[1])}</p><div class="grid2">${a.slice(2).map(x=>`<div class="source" style="background:#f5f6ee;border-radius:7px"><h3 style="font-size:16px">${t(...x[0])}</h3><p>${t(...x[1])}</p></div>`).join('')}</div></div><div class="notice">${t('證據原則：觀察 → 解讀 → 選項 → 適用條件 → 限制與下一步驗證。所有重要策略判斷仍須由團隊確認。','Evidence principle: observation → interpretation → option → conditions → limitations and next validation. Important strategic judgments require team review.')}</div>`}
function events(){return head('03 / STRATEGIC TIMELINE',t('記錄行動，<em>保留脈絡。</em>','Document actions.<br><em>Preserve context.</em>'),t('具日期、原文與來源的事件，才能用來分析發展歷程。此處先展示事件閱讀方式。','Dated events with original passages and sources can support historical analysis. This prototype demonstrates the reading experience.'))+`<div class="notice">${t('尚未匯入已驗證事件。以下為待蒐集的事件類型，不是真實歷史時間軸；不預填年份或因果關係。','No verified events imported. The following are collection categories, not historical events; no dates or causal links are invented.')}</div><div class="timeline">${[['展店與區域發展','Store expansion'],['店型與產品調整','Format & product changes'],['加盟與營運制度','Franchise & operations'],['會員與通路合作','Membership & channels']].map((x,i)=>`<div class="event"><button class="study" data-event="${i}" aria-expanded="false"><span class="small">DATE TBD · ${t('待蒐集','PENDING COLLECTION')}</span><strong>${t(...x)} <span style="float:right">＋</span></strong><p>${t('點擊查看正式事件所需的證據欄位。','Click to see the evidence required for a verified event.')}</p><div class="hidden event-detail" style="border-top:1px solid var(--line);margin-top:17px;padding-top:15px"><p>${t('事件日期／公告日期／取得日期：待確認','Event / announcement / retrieval dates: pending')}<br>${t('原文依據與來源：待蒐集','Original passage and source: pending')}<br>${t('AMC 解讀：待證據與人工審核','AMC interpretation: pending evidence and review')}<br>${t('對手相關行動：尚無回應證據','Competitor action: no response evidence yet')}<br>${t('證據限制：不得僅由時間相近推論競爭回應。','Limit: events close in time do not establish a competitive response.')}</p></div></button></div>`).join('')}</div>`}
function agent(){let steps=[['指定來源與匯入','Source & import','保留來源、觀察日期、公告日期與取得日期。','Retain source, observation, announcement and retrieval dates.'],['資料整理與檢查','Clean & validate','檢查重複、缺漏、營業狀態、座標與來源矛盾。','Check duplicates, missingness, operating status, coordinates and conflicts.'],['計算與分析草稿','Calculate & draft','固定規則計算指標；AI 擷取事件並協助起草。','Calculate metrics by fixed rules; AI extracts events and assists drafting.'],['重要內容人工審核','Human review','策略判斷、因果關係及建議由團隊確認。','The team confirms strategic judgments, causal claims and recommendations.'],['輸出 JSON','Export JSON','輸出已確認版本，保留證據標籤與版本紀錄。','Export confirmed versions with evidence labels and version history.'],['網站呈現','Website delivery','呈現地圖、圖表、事件與策略，揭露資料日期。','Present maps, comparisons, events and strategy with data dates.']];return head('04 / BEHIND THE RESEARCH',t('Agent 整理資料，<br><em>研究者做出判斷。</em>','Agents organize data.<br><em>Researchers judge.</em>'),t('從指定來源到互動網站，讓每一個觀察都有可回查的依據。下列為規劃流程，目前未串接自動化服務。','From designated sources to an interactive website, every observation needs traceable evidence. This is a planned workflow; automation is not connected.'))+`<div class="workflow">${steps.map((s,i)=>`<div class="study"><span class="index">0${i+1}</span><h3>${t(s[0],s[1])}</h3><p>${t(s[2],s[3])}</p><span class="badge">${t('流程規劃','Planned')}</span></div>`).join('')}</div><div class="video"><div class="play">▷</div><div><h2>${t('兩分鐘，認識這項研究','Two minutes to meet the research')}</h2><p>${t('雙語介紹影片尚待製作。預計涵蓋研究問題、操作示範，以及經確認後的發現與建議。','Bilingual introduction video pending production. Planned: research questions, a walkthrough, and verified findings and recommendations.')}</p></div></div><div class="notice">${t('零付費雲端更新、免費 API 與自由問答均待可行性驗證。此原型不提供即時 AI 回答或自動擷取。','Free cloud updates, API quotas and open-ended Q&A await feasibility testing. This prototype has no live AI answers or automated collection.')}</div>`}
function sources(){let rows=[['品牌門市資料','Brand store lists','Q Burger 官方門市查詢、臺北市食材登錄平台與品牌資料交叉確認。','Q Burger store finder, Taipei food ingredient registry, and brand cross-checks.'],['交通與人口','Transport & population','政府捷運出入口座標、人口與戶數；僅提供環境背景。','Government MRT entrance coordinates, population and households; contextual use only.'],['財務與營運','Finance & operations','MOPS、公司年報、財報與法說；區分公司、品牌與地理範圍。','MOPS, annual reports, financial statements and investor materials; distinguish company, brand and geography.'],['歷史事件與服務','Historical events & services','具日期公告、品牌沿革、菜單、加盟與會員服務規則。','Dated announcements, brand history, menus, franchise and membership terms.']];return head('05 / EVIDENCE & TRANSPARENCY',t('知道什麼，<em>也說明未知。</em>','Show what is known.<br><em>Explain what is missing.</em>'),t('本原型依 TP proposal.md 建立。未另外查核企業與市場事實，也尚未匯入正式研究資料。','Built from TP proposal.md. Company and market facts have not been independently verified; research datasets have not been imported.'))+`<div class="grid2">${rows.map(x=>`<div class="panel source"><span class="badge">${t('預計來源 · 尚未取得','Planned source · not acquired')}</span><h3 style="margin-top:15px">${t(x[0],x[1])}</h3><p>${t(x[2],x[3])}</p></div>`).join('')}</div>`+section(t('證據標示與版本','Evidence labels & versions'),'TRACEABLE BY DESIGN')+`<div class="panel analysis"><div class="grid2"><div><h3 style="font-size:16px">${t('三種結論狀態','Three evidence states')}</h3><p>${t('來源直接支持：原始資料直接支持且口徑一致。','Direct support: original evidence and aligned scope.')}<br>${t('多項資料支持的推論：列出推論步驟與替代解釋。','Supported inference: document reasoning and alternatives.')}<br>${t('待驗證假設：說明缺少什麼、如何驗證。','Hypothesis: explain missing evidence and validation.')}<br>${t('公司說法須另標示，不直接當成已證實成效。','Company statements receive a separate label, not proof of impact.')}</p></div><div><h3 style="font-size:16px">${t('目前版本狀態','Current version status')}</h3><p>${t('資料觀察日期：TBD','Observation date: TBD')}<br>${t('資料版本日期：尚未匯入','Data version date: not imported')}<br>${t('分析版本日期：尚未審核','Analysis version date: not reviewed')}<br>${t('介面版本：v0.1 · 2026-11-08','Interface version: v0.1 · 2026-11-08')}<br>${t('更新摘要：首次互動介面原型。','Update: initial interactive interface prototype.')}</p></div></div><hr style="border:0;border-top:1px solid var(--line)"><p>${t('門市品質報告：原始、去重後、有效、缺漏、待確認與排除筆數均尚未產生；各指標分母 TBD。尚無可發布的量化結果。','Store quality report: raw, deduplicated, valid, missing, pending and excluded counts are not available; metric denominators TBD. No quantitative findings are ready for publication.')}</p></div><div class="notice">${t('研究界線：門市數量不是市占率；鄰近不等於競爭強度；同期不等於回應；成長不等於特定策略有效。全台公司數據不能直接解釋台北單店表現。','Research limits: store counts are not market share; proximity is not competitive intensity; contemporaneous events are not responses; growth does not prove a strategy worked. National company data cannot directly explain Taipei store performance.')}</div>`}
function bind(){document.getElementById('lang').onclick=()=>{state.en=!state.en;render()};document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelectorAll('[data-framework]').forEach(b=>b.onclick=()=>{state.framework=[0,1,2][+b.dataset.framework];go('background')});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.framework=+b.dataset.tab;render()});document.querySelectorAll('[data-pin]').forEach(b=>b.onclick=()=>{state.selected=+b.dataset.pin;render()});['q','m'].forEach(k=>{let el=document.getElementById(k+'-toggle');if(el)el.onchange=()=>{state[k]=el.checked;state.selected=null;render()}});let d=document.getElementById('district');if(d)d.onchange=()=>{state.district=d.value;state.selected=null;render()};document.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>{let e=b.querySelector('.event-detail');e.classList.toggle('hidden');b.setAttribute('aria-expanded',!e.classList.contains('hidden'))})}
const L=(zh,en)=>t(zh,en);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const summaries=[['切入、擴張、維持競爭地位：從三個問題看懂研究全貌。','Entry, expansion and sustained position: three questions define the research.'],['誰是主角？比較什麼？在哪裡、哪個期間進行研究？','Who is the focus, what is compared, and where and when is the study conducted?'],['每一種資料，都對應一個要回答的問題。','Each dataset serves a specific research question.'],['從公開資料到互動成果，六個步驟看懂 Agent 的分工。','Six steps from public evidence to interactive outputs.'],['先操作成果示意，再看每種畫面能回答什麼。','Try the output demonstration and see what each view can answer.'],['這項研究能帶來什麼？正式分析前還缺什麼？','What can this study contribute, and what is still needed?']];
function compact(html){return html.replace(/^<div class="hero">[\s\S]*?<\/div><\/div><\/div>/,'')}
function table(headers,rows){return `<div class="panel table-wrap visual-table"><table><thead><tr>${headers.map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map((x,i)=>`<${i?'td':'th'} ${i?'':'scope="row"'}>${x}</${i?'td':'th'}>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function title(zh,en){return section(L(zh,en),en.toUpperCase())}
function flow(items){return `<div class="flow">${items.map((x,i)=>`<div class="flow-node"><span>0${i+1}</span><strong>${x[0]}</strong><small>${x[1]}</small></div>`).join('')}</div>`}
function tiles(items){return `<div class="cards">${items.map((x,i)=>`<div class="study"><span class="index">0${i+1}</span><h3>${x[0]}</h3><p>${x[1]}</p>${x[2]?`<span class="badge">${x[2]}</span>`:''}</div>`).join('')}</div>`}
function label(zh,en){return `<span class="badge">${L(zh,en)}</span>`}
function backgroundVisual(){return tiles([[L('如何切入？','How to enter?'),L('客群 × 產品 × 店型 × 通路','Customers × products × formats × channels')],[L('如何擴張？','How to expand?'),L('區域布局 × 直營加盟 × 數位服務','Locations × ownership models × digital services')],[L('如何維持競爭地位？','How to sustain?'),L('顧客關係 × 競爭回應 × 經營能力','Relationships × responses × capabilities')]])+title('為什麼做這項研究？','Why this research?')+table([L('起點','Starting point'),L('研究要解決的問題','Research need'),L('讀者得到什麼','Reader value')],[ [L('成熟早餐市場','Established breakfast market'),L('後進品牌如何找到位置？','How can a later entrant find a position?'),L('理解策略選擇與適用條件','Understand choices and conditions')],[L('資訊分散','Scattered information'),L('門市、年報與公告缺乏整合','Stores, annual reports and announcements are disconnected'),L('有來源、可比較的發展脈絡','Traceable, comparable context')],[L('學生與潛在創業者','Students & potential entrepreneurs'),L('如何把熟悉案例轉為策略學習？','How can a familiar case support learning?'),L('看懂證據，不套用成功公式','Read evidence without assuming a universal formula')]])+title('一條分析路徑','The analytical path')+flow([[L('外部環境','Environment'),'PESTEL'],[L('門市布局','Store locations'),L('台北市暫定','Taipei tentative')],[L('競合與賽局','Co-opetition'),L('競爭 × 合作','Compete × cooperate')],['AMC',L('察覺・動機・能力','Awareness · motivation · capability')],[L('平台策略','Platforms'),L('外送 × 自有服務','Delivery × owned services')],[L('策略選項','Options'),L('條件與限制','Conditions & limits')]])+title('研究問題如何對應資料？','Questions to evidence')+table([L('具體問題','Question'),L('分析方式','Approach'),L('不能直接推論','What cannot be inferred')],[[L('哪些區域面對較多麥味登？','Where are more My Warm Day stores nearby?'),L('區域分布與雙向競品鄰近','Distribution and two-way proximity'),L('不能從當期布局倒推歷年擴張','Current distribution does not reconstruct expansion')],[L('重疊區域如何差異化？','How to differentiate in overlapping areas?'),L('產品、價格、店型與服務比較','Products, prices, formats and services'),L('缺顧客資料時不判定偏好或成效','No preference or impact claims without customer evidence')],[L('合作通路如何支持發展？','How do partners and channels support development?'),L('加盟、外送、自有服務與 AMC','Franchising, delivery, owned services and AMC'),L('App 存在不等於多邊平台','An app does not establish a multisided platform')]])
+title('PESTEL：外部變化如何影響企業選擇？','PESTEL: external changes and corporate choices')
+table([L('面向','Dimension'),L('研究問題與所需證據','Questions and evidence'),L('解讀界線','Interpretation limits')],[
['P · '+L('政治','Political'),L('政策與公共支持如何影響擴張和營運？比對政策公告、實施日期及企業揭露。','How do policy and public support affect expansion and operations? Compare policy notices, effective dates and corporate disclosures.'),L('政策存在不代表已直接影響 Q Burger。','A policy alone does not establish a direct impact on Q Burger.')],
['E · '+L('經濟','Economic'),L('原料、勞動成本與消費支出變化下，兩品牌如何調整價格、產品或營運？使用政府統計、財報與具日期公告。','How do the brands adjust prices, products or operations as ingredient costs, labor costs and spending change? Use official statistics, financial reports and dated notices.'),L('產業統計不能直接解釋單店表現；保留其他解釋。','Industry statistics cannot explain individual-store performance directly; retain alternative explanations.')],
['S · '+L('社會','Social'),L('人口、家戶、通勤與生活型態如何對應門市布局？使用人口、戶數、交通與消費研究。','How do population, households, commuting and lifestyles relate to locations? Use demographic, household, transport and consumer research.'),L('地理鄰近與人口特徵不直接證明顧客偏好。','Proximity and demographics do not establish customer preferences.')],
['T · '+L('科技','Technological'),L('比較點餐、支付、會員與外送；辨識品牌自主服務和外部依賴，核對服務規則及上線日期。','Compare ordering, payments, membership and delivery; distinguish owned services from external dependencies using service terms and launch dates.'),L('功能存在不等於營收、留存或效率提升。','Available features do not prove revenue, retention or efficiency gains.')],
['E · '+L('環境','Environmental'),L('包材、廚餘、能源與資源管理如何影響成本與差異化？使用環境統計、政策及企業永續揭露。','How do packaging, food waste, energy and resource management affect costs or differentiation? Use environmental statistics, policies and corporate sustainability disclosures.'),L('環境措施是否改善獲利與競爭力，仍需證據。','Profitability and competitive benefits require supporting evidence.')],
['L · '+L('法律','Legal'),L('食品安全、勞動、消費者保護與加盟法規帶來哪些責任？核對法規原文、生效日期及企業揭露。','Which duties arise from food safety, labor, consumer protection and franchise rules? Check official texts, effective dates and corporate disclosures.'),L('區分法定義務與自願措施；不能自行推定合規或違規。','Separate legal duties from voluntary practices; do not infer compliance or violations.')]
])
+flow([[L('外部變化','External change'),L('優先選擇相關因素','Prioritize relevant factors')],[L('潛在營運影響','Potential impact'),L('連結企業選擇','Connect to decisions')],[L('有證據的企業行動','Evidenced actions'),L('原始來源與日期','Original sources and dates')],[L('待驗證結果','Outcomes to verify'),L('六面向不必平均涵蓋','Coverage need not be equal')]])
+title('從布局到策略：各階段怎麼分析？','From locations to strategic interpretation')
+table([L('階段','Stage'),L('分析與產出','Analysis and output'),L('證據界線','Evidence boundary')],[
[L('門市分布','Store distribution'),L('同一觀察日期比較總店數、行政區店數與品牌內區域占比；計算最近競品距離、指定距離內店數及雙向鄰近比例。','Compare totals, district counts and within-brand regional shares at a common date; calculate nearest-competitor distance, counts within thresholds and two-way proximity.'),L('距離門檻與直線／步行方式 TBD；比較不同門檻的穩定性。店數不是市占率，鄰近不是顧客重疊或跟隨選址。','Thresholds and straight-line/walking methods TBD; compare sensitivity. Counts are not market share; proximity is not customer overlap or follower location selection.')],
[L('區域案例','Area cases'),L('依事先定義標準，挑選雙方密集、麥味登多而 Q Burger 少、Q Burger 多而麥味登少的對照區。','Use predefined criteria to select areas dense in both brands, more My Warm Day/fewer Q Burger, and the reverse.'),L('案例用於理解情境，不直接形成投資建議。','Cases explain context and do not directly yield investment recommendations.')],
[L('競合與賽局','Co-opetition and games'),L('比較產品、價格、店型、時間與服務；整理加盟、外送、支付及科技夥伴的資源交換與控制張力。以「相近定位／差異化 × 對手維持／調整」討論質性情境。','Compare products, prices, formats, hours and services; examine resource exchange and control tensions with franchise, delivery, payment and technology partners. Discuss similar positioning/differentiation × competitor holds/adjusts.'),L('共用平台不等於兩品牌合作；無充分資料不填報酬、不宣稱均衡、最佳策略或成效。','Shared platforms do not establish inter-brand cooperation; no invented payoffs, equilibrium, optimal-strategy or impact claims.')],
['AMC',L('選取具日期與原文的事件：A 檢查公司是否公開察覺；M 區分公司目的與團隊推論；C 檢查加盟、供應、技術、管理及財務資源。','Select dated, source-backed events: A checks public awareness; M separates stated purposes from team inference; C examines franchise, supply, technology, management and financial resources.'),L('對手行動分為明確回應、可能相關但不足、僅同期；依「事實 → AMC → 對手行動 → 後續觀察 → 限制」呈現。','Classify competitor actions as evidenced responses, possibly related but insufficient, or merely contemporaneous; present facts → AMC → competitor actions → follow-up → limits.')],
[L('平台策略','Platform strategy'),L('比較外送、自有點餐與會員的接觸、交易、顧客關係、合作成本及依賴；能確認個店服務時才做區域比較。','Compare delivery, owned ordering and membership by discovery, transactions, relationships, costs and dependencies; compare areas only when store-level services are verified.'),L('品牌級資訊不能套用每店；未公開的抽成、流量、獲利與會員貢獻維持資料不足。App 不等於多邊平台。','Brand-level information does not establish every store’s services; undisclosed commissions, traffic, profits and member contribution remain unknown. An app is not proof of a multisided platform.')]
])
+title('商業洞察與有條件的策略選項','Business insights and conditional options')
+tiles([[L('重疊區域差異化','Differentiate in overlapping areas'),L('評估產品、店型與服務；仍需需求證據。','Evaluate products, formats and services; demand evidence is still needed.')],[L('據點較少區域','Less-covered areas'),L('先確認需求及經營條件，再討論發展。','Verify demand and operating conditions before evaluating expansion.')],[L('加盟與通路組合','Franchise and channel mix'),L('確認加盟管理能力，評估第三方通路與自有服務搭配。','Check franchise management capacity and evaluate third-party/owned service combinations.')]])
+flow([[L('觀察','Observation'),L('資料顯示什麼？','What do data show?')],[L('解讀','Interpretation'),L('保留可能原因','Retain possible explanations')],[L('選項','Option'),L('Q Burger 可評估什麼？','What can Q Burger evaluate?')],[L('條件','Conditions'),L('資源與先決條件','Resources and prerequisites')],[L('限制','Limitations'),L('缺口與下次驗證','Gaps and next validation')]])
+`<div class="notice">${L('研究範圍暫定台北市，待兩品牌名單完整度與比較價值確認。早期切入與歷年擴張需要歷史資料；當期布局只代表觀察日的分布。首店年份與品牌沿革仍待原始來源核實。以下均為研究問題與方法，尚非研究發現。','Taipei City is provisional pending list coverage and comparative value. Entry and expansion require historical records; current locations describe the observation date only. First-store dates and brand histories await original-source verification. These are research questions and methods, not findings.')}</div>`
}
function firmVisual(){return `<div class="brand-match"><div class="brand-block"><span>FOCAL BRAND</span><h2>Q Burger</h2><p>${L('饗樂餐飲實業','Xiang Le Food & Beverage Industrial')}</p><b>7797</b></div><div class="versus">VS<span>${L('主要比較','COMPARATOR')}</span></div><div class="brand-block secondary"><span>MAIN COMPARATOR</span><h2>${L('麥味登','My Warm Day')}</h2><p>${L('揚秦國際企業','Young Qin International')}</p><b>2755</b></div></div><div class="micro-note">${L('企業名稱、代號與品牌關係依提案整理，正式引用前待官方確認。','Names, stock codes and brand relationships follow the proposal and await official verification.')}</div>`+title('為什麼選 Q Burger？','Why Q Burger?')+tiles([[L('研究問題契合','Fits the question'),L('觀察較晚進入市場的品牌如何發展；首店與歷史待核實。','Examine a later entrant’s development; first-store dates and history need verification.')],[L('行動可具體比較','Observable strategic actions'),L('展店、加盟、店型、點餐、會員及外送合作。','Expansion, franchising, formats, ordering, membership and delivery.')],[L('證據可互相補充','Complementary evidence'),L('空間資料 × 企業公告 × 經營背景。','Spatial data × announcements × operating context.')]])+title('比較範圍一覽','Scope at a glance')+table([L('面向','Dimension'),L('本研究設定','Study scope'),L('狀態／界線','Status / boundary')],[[L('產業','Industry'),L('台灣連鎖早餐與早午餐','Taiwan chain breakfast & brunch'),L('全台資料作背景','National data provide context')],[L('空間範圍','Geography'),L('台北市','Taipei City'),label('暫定，待確認完整度','Tentative; coverage pending')],[L('觀察期間','Period'),L('兩品牌共同可比較期間','Common comparable period'),label('TBD · 歷史與當期分開','TBD · history and snapshot separate')],[L('其他品牌','Other brands'),L('早安美芝城、拉亞漢堡','Good Morning MACC, Laya Burger'),L('僅產業背景，量化納入 TBD','Background only; quantitative inclusion TBD')],[L('比較口徑','Data scope'),L('公司財務／品牌門市分開','Separate company finances and brand stores'),L('合併營收不等於品牌營收','Consolidated revenue is not brand revenue')]])}
function sourcesVisual(){let data=[
['門市','Stores','品牌官方名單、台北市食材登錄','Official store lists, Taipei ingredient registry','品牌、地址、行政區、座標、日期','Brand, address, district, coordinates, dates','布局、店數、競品鄰近','Distribution, counts, proximity','完整度、營業狀態、座標','Coverage, operating status, coordinates'],
['交通與人口','Transit & population','政府捷運出入口、人口戶數','Government MRT entrances, population, households','站點座標、行政區、統計年月','Entrance coordinates, districts, statistical dates','交通住宅背景、捷運鄰近','Transit context, MRT proximity','版本、邊界與距離門檻','Versions, boundaries, thresholds'],
['財務營運','Financial operations','MOPS、年報、財報、法說','MOPS, annual reports, financials, presentations','營收、毛利、營業利益、直營加盟','Revenue, gross profit, operating profit, ownership','共同期間的營運背景','Operating context for common periods','品牌揭露與指標可比性','Brand disclosure and comparability'],
['歷史事件','Historical events','具日期公告、年報、品牌沿革','Dated announcements, reports, histories','發生／公告日期、行動、原文','Event / announcement dates, action, passage','時間軸、AMC、行動回應','Timeline, AMC, action / response','早期缺口與回應證據','Early gaps and response evidence'],
['定位與服務','Positioning & services','官網、菜單、加盟、會員規則','Websites, menus, franchise and member terms','價格帶、店型、功能、適用門市','Price range, format, features, applicable stores','品牌差異與通路角色','Brand differences and channel roles','時間／門市適用差異','Time and store applicability'],
['產業與 PESTEL','Industry & PESTEL','經濟部統計、政府政策原文','MOEA statistics, original government policies','定義、期間、數值、範圍','Definition, period, value, scope','外部環境與企業決策','External conditions and decisions','整體餐飲不等於早餐市場','Foodservice is not the breakfast market']
];return title('資料需求矩陣','Data requirements matrix')+table([L('資料類型','Dataset'),L('預計來源','Planned source'),L('必要欄位','Required fields'),L('用途','Use'),L('待查核','Check')],data.map(x=>[L(x[0],x[1]),L(x[2],x[3]),L(x[4],x[5]),L(x[6],x[7]),L(x[8],x[9])]))+`<div class="micro-note">${L('以上皆為預計來源，尚未匯入或查核；來源連結與觀察日期待確認。','All sources are planned, not imported or verified; source links and observation dates are pending.')}</div>`+title('先蒐集什麼？','Acquisition priority')+flow([[L('兩品牌門市名單','Both store lists'),L('同一觀察期間','Same observation period')],[L('公司年報與營運','Reports & operations'),L('共同期間、同口徑','Common period and definitions')],[L('少量具來源事件','A few traceable events'),L('具日期與原文','Dated, original passages')]])+title('資料進入分析前的五道關卡','Five evidence gates')+flow([[L('核對來源','Trace source'),L('政府／公司原始資料優先','Prefer original sources')],[L('門市查核','Check stores'),L('去重、座標、營業狀態','Duplicates, coordinates, status')],[L('處理衝突','Resolve conflicts'),L('保留差異與採用理由','Keep differences and rationale')],[L('標示證據','Label evidence'),L('事實／推論／假設','Fact / inference / hypothesis')],[L('人工審核與版本','Review & version'),L('確認者、時間與修改紀錄','Reviewer, time, change log')]])+table([L('證據標籤','Evidence label'),L('採用條件','Requirement')],[[label('來源直接支持','Direct support'),L('原文支持，期間、地區及品牌口徑一致','Original support with aligned period, geography and brand')],[label('多項資料支持的推論','Supported inference'),L('列出獨立證據、推論步驟與替代解釋','Independent evidence, reasoning and alternatives')],[label('待驗證假設','Hypothesis'),L('列明缺少證據與驗證方法，不能當成發現','State missing evidence and validation; not a finding')],[label('公司說法（另標）','Company statement (additional)'),L('官方聲明不直接當成已證實成效','Official statements do not prove effectiveness')]])}
function agentVisual(){return title('Agent 的目的與資料範圍','Agent purpose and evidence scope')
+tiles([[L('資料與分析助手','Data and analysis assistant'),L('聚焦 Q Burger、主要比較麥味登；暫定台北市的門市空間分析，協助理解成熟市場中的品牌發展。','Focus on Q Burger with My Warm Day as comparator; provisional Taipei store analysis supports understanding development in a mature market.')],[L('指定公開來源','Designated public sources'),L('門市、捷運出入口、人口戶數、年報財報與法說、具日期公告及 PESTEL 政府資料。','Stores, metro entrances/exits, population/households, annual/financial/investor reports, dated announcements and PESTEL government data.')],[L('研究者負責判斷','Researchers confirm judgments'),L('競爭意圖、因果與策略建議由團隊確認；來源完整度、取得方式、歷史期間與版本仍待核實。','The team confirms intent, causality and strategic advice; source coverage, acquisition methods, historical periods and versions remain pending.')]])
+title('每週工作流程：從候選資料到已確認內容','Planned weekly workflow: candidates to confirmed content')
+flow([[L('來源更新／搜尋／匯入','Updates / search / import'),L('公告、RSS、關鍵字與人工補充','Announcements, RSS, keywords and manual input')],[L('整理與檢查','Organize and check'),L('格式、缺漏、異常與衝突','Formats, gaps, anomalies and conflicts')],[L('指標與 AI 草稿','Metrics and AI drafts'),L('固定規則＋事件原文','Fixed rules and event evidence')],[L('人工審核','Human review'),L('新來源與重要判斷先確認','Confirm new sources and key judgments')],[L('JSON 輸出','JSON output'),L('僅通過檢查與必要審核版本','Checked and reviewed content only')],[L('網站呈現','Website presentation'),L('規劃 GitHub Pages 讀取 JSON','Planned GitHub Pages reads JSON')]])
+title('六步流程的檢查與交付物','Six steps: checks and deliverables')
+table([L('步驟','Step'),L('處理內容','Processing'),L('檢查與交付','Checks and outputs')],[
[L('01 取得資料','01 Acquisition'),L('指定頁面與 RSS 更新、品牌／競品／產業關鍵字搜尋；初期人工搜尋、下載與匯入；候選文章去重、摘要、分類。','Update designated pages/RSS and search brand, competitor and industry keywords; supplement manual search/download/import initially; deduplicate, summarize and classify candidate articles.'),L('保留來源、資料基準日、取得日；事件另記發生日與公告日。新來源經團隊確認才入正式資料庫；免費搜尋 TBD。','Retain source, reference and retrieval dates; separate event and announcement dates. Confirm new sources before formal inclusion; free search TBD.')],
[L('02 整理資料','02 Organization'),L('統一品牌、店名、地址、日期與單位；檢查重複、缺漏、座標、營業狀態與來源衝突。','Standardize brands, names, addresses, dates and units; check duplicates, gaps, coordinates, operating status and conflicts.'),L('新增或消失先列待確認，不直接判定開閉店。依 3.8.3 檢查；轉換工具與誤差門檻 TBD。','Treat additions/disappearances as candidates, not confirmed openings/closures. Follow 3.8.3; conversion tools and error thresholds TBD.')],
[L('03 指標與草稿','03 Metrics and drafts'),L('計算總店數、行政區店數與占比、最近競品距離、距離內店數、雙向鄰近與捷運鄰近；擷取具日期事件，草擬 PESTEL、競合、AMC 與平台分析。','Calculate totals, district counts/shares, nearest-competitor distance, counts within thresholds, two-way and metro proximity; extract dated events and draft PESTEL, co-opetition, AMC and platform analysis.'),L('門檻、距離法與納入條件待確認；揭露缺漏與分母，AI 不補造數值。事件區分事實、公司說法、團隊解讀與缺口；鄰近不等於競爭，先後不等於回應或成效。','Confirm thresholds, distance methods and inclusion; disclose gaps and denominators, with no invented values. Separate facts, company statements, interpretations and gaps; proximity is not competition, sequence is not response or impact.')],
[L('04 人工審核','04 Review'),L('固定格式與已確認公式的結果通過檢查才更新；門市變動、異常與衝突人工確認；新策略判斷、AMC、回應與建議審核後發布。','Update standard formats and confirmed-formula results after checks; manually confirm store changes, anomalies and conflicts; review new judgments, AMC, responses and advice before release.'),L('依 3.8 五項規則確認來源、標籤、門市品質、衝突及版本。記錄確認者、時間、變更與原因；未通過保留草稿，未確定自動發布條件前先人工確認。','Apply 3.8 source, label, store-quality, conflict and version rules. Record reviewer, time, changes and reasons; unapproved work remains draft and updates require human confirmation until automated release conditions are established.')],
[L('05 JSON','05 JSON'),L('輸出通過檢查與必要審核的門市、指標與事件；保留來源名稱、資料及取得日期、結論證據類別、確認者與時間、審核狀態及資料／分析版本識別與日期。','Export checked/reviewed stores, metrics and events with source names, reference/retrieval dates, conclusion evidence labels, reviewers/times, review status and data/analysis version identifiers and dates.'),L('來源連結可於資料確認時補入；欄位結構、產製工具與版本管理 TBD。AI 重要判斷須先審核。','Add source links during confirmation; schema, production tools and version management TBD. Review important AI judgments before release.')],
[L('06 網站','06 Website'),L('規劃由 GitHub Pages 讀取 JSON，呈現地圖、圖表、事件與策略，標示資料日期與限制。','Plan for GitHub Pages to read JSON and show maps, charts, events and strategy with dates and limits.'),L('資料處理、AI 與 JSON 流程另行規劃；完整零付費可行性 TBD。此為提案目標，本展示目前使用現有分享網址。','Processing, AI and JSON production are planned separately; end-to-end zero-cost feasibility TBD. This is the proposal target; this demonstration uses its existing sharing URL.')]
])
+title('各來源：自動化與人工如何分工？','Source-specific automation and human responsibilities')
+table([L('資料','Data'),L('自動化處理規劃','Planned automation'),L('人工責任','Human responsibilities')],[
[L('官方新聞與活動','Official news and campaigns'),L('每週檢查指定頁面；AI 擷取日期、行動、夥伴與原文。','Check designated pages weekly; AI extracts dates, actions, partners and original text.'),L('判定研究價值與是否構成競爭回應。','Decide relevance and whether a competitive response is evidenced.')],
[L('一般新聞與訪談','News and interviews'),L('可用 RSS／搜尋工具取得候選文章，AI 去重、摘要與分類。','Use confirmed RSS/search tools for candidate articles; AI deduplicates, summarizes and classifies.'),L('初期補充搜尋；核對重大事件、轉述與公司說法；免費搜尋 TBD。','Supplement initial searches; verify major events, secondhand accounts and company claims; free search TBD.')],
[L('門市名單','Store lists'),L('初始查核後每週比較變化，以已確認資料重算指標。','After initial verification, compare weekly changes and recalculate using confirmed data.'),L('初始確認涵蓋範圍；查核新增、消失、搬遷與異常座標。','Confirm initial coverage; verify additions, disappearances, relocations and anomalous coordinates.')],
[L('人口與捷運開放資料','Population and metro open data'),L('檢查版本、下載更新、欄位檢查及重新計算。','Check versions, download updates, validate fields and recalculate.'),L('確認定義與範圍，處理欄位或統計口徑改變。','Confirm definitions/scope and resolve field or statistical-definition changes.')],
[L('月營收、財報與年報','Revenue and financial/annual reports'),L('檢查新揭露；固定格式整理，AI 輔助擷取並附頁碼。','Check new disclosures; organize fixed formats and use AI extraction with page references.'),L('初始手動下載匯入；核對數字、公司／品牌與合併／個別口徑。','Initially download/import manually; verify figures, company/brand and consolidated/separate bases.')],
[L('早期歷史、加盟、會員與平台條款','History, franchise, membership and platform terms'),L('檢查指定頁面變更，標記可能影響分析內容。','Check designated pages for changes and flag potential analytical impacts.'),L('建立歷史基準，確認適用日期、門市與條款含義。','Establish a historical baseline and verify dates, stores and meaning of terms.')],
[L('策略洞察與建議','Insights and recommendations'),L('根據新證據起草，標記需重新檢視的結論。','Draft from new evidence and flag conclusions for reconsideration.'),L('發布前審核新判斷、因果、賽局情境與建議。','Review new judgments, causal explanations, game scenarios and advice before release.')]
])
+title('工具角色：取得、AI、處理與排程','Tool roles: acquisition, AI, processing and scheduling')
+table([L('工具','Tool'),L('專案角色','Project role')],[
[L('資料取得工具','Acquisition tools'),L('下載公開資料、讀取指定公告與 RSS；有可用搜尋 API 時尋找新聞。','Download public data and read designated announcements/RSS; find news when a search API is available.')],
['AI API',L('從取得的文章擷取事件、摘要與分類，協助 PESTEL、競合、AMC 與平台分析草稿。','Extract events, summarize and classify retrieved articles; assist PESTEL, co-opetition, AMC and platform drafts.')],
['Python',L('協調資料取得與 API 呼叫；清理、去重、距離計算、新舊版本比較及 JSON 輸出。','Coordinate acquisition/API calls; clean, deduplicate, calculate distances, compare versions and export JSON.')],
[L('雲端排程','Cloud scheduler'),L('規劃每週觸發 Python；具體服務、工具與免費額度可行性 TBD。','Plan weekly Python execution; services, tools and free-quota feasibility TBD.')]
])
+title('部署、失敗處理與延伸問答','Deployment, failure handling and optional Q&A')
+tiles([[L('零付費雲端目標','Zero-cost cloud target'),L('規劃 GitHub Pages＋每週雲端 Python，不依賴團隊電腦持續開機；取得、排程、AI 的免費額度與可靠性尚未驗證。','Plan GitHub Pages plus weekly cloud Python without keeping team computers on; free acquisition, scheduling, AI quotas and reliability remain unverified.'),L('規劃，尚未串接','Planned, not connected')],[L('更新失敗保留上一版','Retain last confirmed version'),L('保留已確認資料、顯示資料日期並通知負責人；排程工具、實際週期、負責人與通知方法 TBD。','Retain confirmed data, display dates and notify the responsible person; scheduler, actual frequency, reviewers and notification methods TBD.'),L('待可行性測試','Feasibility pending')],[L('自由問答為延伸功能','Open Q&A is optional'),L('非首版確定交付。免費 API 與技術測試通過後才決定；若實作，僅引用已確認資料並附來源，資料不足說明缺口，額度不足暫停即時回答，既有圖表仍可讀。','Not a committed first-version deliverable. Decide after free API/technical tests; if implemented, cite confirmed evidence, explain gaps and suspend live answers when quotas run out while existing views remain readable.'),L('模型、後端與限制 TBD','Model, backend and limits TBD')]])
+`<div class="notice">${L('以上為 TP proposal_v2 的規劃流程，尚未啟用自動擷取、每週排程或即時 AI。Agent 整理門市、計算指標、擷取事件及附原文；PESTEL 關係、AMC、賽局推論與策略建議仍由研究團隊確認。','This is the planned TP proposal_v2 workflow; automated retrieval, weekly scheduling and live AI are not enabled. The Agent organizes stores, calculates metrics, extracts events and attaches passages; the team confirms PESTEL relationships, AMC, game reasoning and strategic advice.')}</div>`}

function strategyMatrix(){return `<div class="tabs">${frameworks.map((x,i)=>`<button class="tab ${state.framework===i?'active':''}" data-tab="${i}">${x[0]} · ${L(x[1],x[2])}</button>`).join('')}</div>`+table([L('分析面向','Dimension'),L('要檢查什麼','What to examine')],analyses[state.framework].slice(2).map(x=>[L(...x[0]),L(...x[1])]))+`<div class="micro-note">${L('研究框架與候選選項，尚非分析發現。','Research framework and candidate options, not findings.')}</div>`}
function outputPreview(){return title('每一種成果，各自回答什麼？','A purpose for every output')+table([L('畫面','View'),L('使用者一眼看懂','Reader takeaway'),L('操作方式','Interaction'),L('目前狀態','Current state')],[[L('門市地圖','Store atlas'),L('品牌分布在哪裡？','Where are brands located?'),L('品牌切換、行政區篩選、點位詳情','Brand toggles, districts, point details'),label('可操作示意','Interactive demo')],[L('比較圖表','Comparisons'),L('店數、區域占比與鄰近程度','Counts, regional share, proximity'),L('同日期、同口徑比較','Common-date, comparable metrics'),label('真實數據待取得','Real data pending')],[L('事件時間軸','Timeline'),L('何時做了什麼？證據是什麼？','What happened when, with what evidence?'),L('點擊展開事實、原文與限制','Expand facts, passages and limits'),label('事件待查核','Events pending')],[L('策略分析','Strategy'),L('可評估哪些選項與條件？','Which options and conditions can be evaluated?'),L('切換 PESTEL／AMC／平台框架','Switch PESTEL / AMC / platform frameworks'),label('框架示意','Framework demo')],[L('雙語影片','Bilingual video'),L('兩分鐘認識研究與操作','Meet the study and interface in two minutes'),L('介紹研究、操作與確認後發現','Questions, walkthrough, verified findings'),label('尚待製作','Not produced')]])+`<div class="tabs">${[['map','地圖與圖表','Map & charts'],['events','事件時間軸','Timeline'],['strategy','策略分析','Strategy'],['video','介紹影片','Video']].map(x=>`<button class="tab ${state.output===x[0]?'active':''}" data-output="${x[0]}">${L(x[1],x[2])}</button>`).join('')}</div>${state.output==='map'?compact(mapPage()):state.output==='events'?compact(events()):state.output==='strategy'?strategyMatrix():flow([[L('研究問題','Research questions'),L('範圍與限制','Scope & limits')],[L('操作介紹','Walkthrough'),L('Agent、地圖、圖表','Agent, maps, charts')],[L('發現與建議','Findings & options'),L('分析完成後填入','After evidence review')]])}<div class="micro-note">${L('地圖與事件為介面示意；資料觀察日期、資料版本、分析版本均待確認。中英文切換不改變研究範圍。','Maps and events demonstrate the interface. Observation date, data version and analysis version are pending. Language switching preserves scope.')}</div>`}
function conclusionsVisual(){return tiles([[L('研究主軸','Research focus'),L('Q Burger 如何切入、擴張與維持競爭地位？','How does Q Burger enter, expand and sustain its position?')],[L('研究方法','Research method'),L('空間布局 × 具日期事件 × 競合策略框架','Spatial distribution × dated events × strategy frameworks')],[L('預期貢獻','Expected contribution'),L('可追溯觀察與有條件的策略選項','Traceable observations and conditional strategic options')]])+title('從觀察到建議的必要順序','From observation to option')+flow([[L('觀察','Observe'),L('資料顯示什麼？','What do data show?')],[L('解讀','Interpret'),L('有哪些替代解釋？','What alternatives exist?')],[L('選項','Options'),L('品牌可以評估什麼？','What can the brand evaluate?')],[L('條件','Conditions'),L('需要哪些資源？','What resources are needed?')],[L('驗證','Validate'),L('缺什麼證據？','Which evidence is missing?')]])+title('正式分析前，還缺哪些拼圖？','Before completed findings')+table([L('待完成項目','Open item'),L('通過條件','Completion criterion'),L('目前狀態','Status')],[[L('門市資料','Store data'),L('完整名單、營業狀態、座標與分母檢查','Coverage, status, coordinates and denominators verified'),label('待驗證','Pending')],[L('歷史紀錄','Historical records'),L('兩品牌涵蓋期間與早期缺口明確','Coverage periods and early gaps disclosed'),label('待取得','Pending collection')],[L('比較口徑','Comparability'),L('公司／品牌、地區、期間及指標一致','Company / brand, geography, period and metrics aligned'),label('待確認','Pending confirmation')],[L('策略判斷','Strategic judgments'),L('原文、證據分類與負責人審核','Original evidence, labels and reviewer approval'),label('尚無研究定稿','No final findings')],[L('零付費雲端更新','Free cloud updates'),L('取得、排程、失敗保留與通知可運作','Retrieval, scheduling, retention and notification tested'),label('可行性 TBD','Feasibility TBD')],[L('自由問答與影片','Q&A and video'),L('免費 API 測試通過；影片完成','Free API feasibility tested; video produced'),label('延伸／待製作','Optional / pending')]])+title('閱讀結果時，守住四個界線','Four interpretation limits')+`<div class="limit-grid">${[['店數','市場占有率','Store count','Market share'],['空間鄰近','顧客重疊或競爭強度','Proximity','Customer overlap or intensity'],['事件同期','競爭回應','Contemporaneous events','Competitive response'],['營收或展店成長','特定策略有效','Revenue or store growth','A strategy’s effectiveness']].map(x=>`<div><strong>${L(x[0],x[2])}</strong><span>≠</span><strong>${L(x[1],x[3])}</strong></div>`).join('')}</div>`}
function render(){let n=pages.indexOf(state.page);if(n<0){state.page='background';n=0}document.documentElement.lang=state.en?'en':'zh-Hant';const content=[backgroundVisual,firmVisual,sourcesVisual,agentVisual,outputPreview,conclusionsVisual][n]();document.getElementById('app').innerHTML=`<div class="shell"><aside><a class="logo" href="#background"><span class="mark">b.</span>Breakfast Atlas</a><div class="logo-sub">早餐・城市・競合</div><div class="small navlabel">SIX-CHAPTER PROPOSAL</div><nav>${navNames.map((x,i)=>`<button class="nav ${n===i?'active':''}" data-go="${pages[i]}" ${n===i?'aria-current="page"':''}><span class="num">0${i+1}</span><span class="nav-copy"><b>${x[1]}</b><small>${x[0]}</small></span></button>`).join('')}</nav><div class="aside-bottom"><span class="badge">${L('六大架構 · 互動原型','SIX CHAPTERS · PROTOTYPE')}</span><p>Q Burger × My Warm Day</p><span>${L('提案內容視覺化','Visual research proposal')}</span></div></aside><main class="main"><header class="top"><span>RESEARCH PROPOSAL / 0${n+1}</span><div class="top-actions"><span class="small"><span class="dot"></span>${L('研究資料待驗證','EVIDENCE PENDING')}</span><button id="lang" class="language">${state.en?'繁體中文':'EN ↗'}</button></div></header><div class="content">${head(`CHAPTER 0${n+1} / AT A GLANCE`,navNames[n][1],L(...summaries[n]))}${content}<div class="chapter-pagination">${n>0?`<button class="textbtn" data-go="${pages[n-1]}">← ${navNames[n-1][1]}</button>`:'<span></span>'}${n<5?`<button class="textbtn" data-go="${pages[n+1]}">${navNames[n+1][1]} →</button>`:''}</div><footer class="bottom"><span>BREAKFAST ATLAS / VISUAL PROPOSAL</span><span>v0.3 · ${L('依提案整理，非研究定稿','Based on the proposal; research draft')}</span></footer></div></main></div>`;bind();document.querySelectorAll('[data-output]').forEach(b=>b.onclick=()=>{state.output=b.dataset.output;render()})}
const aliases={overview:'background',map:'output',strategy:'background',events:'output'};
window.addEventListener('hashchange',()=>{let p=location.hash.slice(1);state.page=aliases[p]||p;render()});state.page=aliases[state.page]||state.page;render();
